def recall_at_k(model, queries, corpus, k=20):
    doc_vecs = embed(model, corpus, kind="document")
    hits = 0
    for q in queries:
        q_vec = embed(model, [q["text"]], kind="query")[0]
        scores = doc_vecs @ q_vec
        top_k = scores.argsort()[::-1][:k]
        if q["answer_id"] in top_k:
            hits += 1
    return hits / len(queries)

